fn canary_exit_position_flatten_residual_venues(
    cfg: &Config,
    state: &GlobalState,
    position_tol_tao: f64,
) -> Vec<usize> {
    let ranked_execution_venues = v2_live_canary_ranked_execution_allowed_venue_indices(cfg);
    cfg.venues
        .iter()
        .enumerate()
        .filter_map(|(venue_index, _)| {
            if ranked_execution_venues
                .as_ref()
                .is_some_and(|allowed| !allowed.contains(&venue_index))
            {
                return None;
            }
            let venue = state.venues.get(venue_index)?;
            (venue.position_tao.is_finite() && venue.position_tao.abs() > position_tol_tao + 1e-9)
                .then_some(venue_index)
        })
        .collect()
}

fn canary_exit_position_flatten_venues(
    cfg: &Config,
    state: &GlobalState,
    position_tol_tao: f64,
) -> Vec<usize> {
    let ranked_execution_venues = v2_live_canary_ranked_execution_allowed_venue_indices(cfg);
    cfg.venues
        .iter()
        .enumerate()
        .filter_map(|(venue_index, _)| {
            if ranked_execution_venues
                .as_ref()
                .is_some_and(|allowed| !allowed.contains(&venue_index))
            {
                return None;
            }
            let venue = state.venues.get(venue_index)?;
            if venue.status != VenueStatus::Healthy {
                return None;
            }
            if live_open_order_count_for_venue(state, venue_index) != 0 {
                return None;
            }
            (venue.position_tao.is_finite() && venue.position_tao.abs() > position_tol_tao + 1e-9)
                .then_some(venue_index)
        })
        .collect()
}

fn mark_canary_exit_position_flatten_incomplete(state: &mut GlobalState) {
    state.kill_switch = true;
    if state.kill_reason == crate::state::KillReason::None {
        state.kill_reason = crate::state::KillReason::CanaryLimitBreach;
    }
}

struct CanaryExitPositionFlattenAccountTruthApply {
    fresh_requested_venues: Vec<usize>,
    position_changed: bool,
}

fn apply_canary_exit_position_flatten_account_truth_snapshot(
    cfg: &Config,
    state: &mut GlobalState,
    snapshot: &CanonicalCacheSnapshot,
    requested_venues: &[usize],
    now_ms: TimestampMs,
    account_state_initialized: &mut [bool],
    applied_account_position_baselines: &mut [Option<f64>],
) -> CanaryExitPositionFlattenAccountTruthApply {
    let requested = requested_venues.iter().copied().collect::<HashSet<_>>();
    let fresh_requested_venues = snapshot
        .account
        .iter()
        .filter_map(|acct| {
            (requested.contains(&acct.venue_index)
                && account_cache_snapshot_fresh(
                    acct,
                    now_ms,
                    account_snapshot_max_age_ms_for_venue(cfg, acct.venue_id.as_ref()),
                ))
            .then_some(acct.venue_index)
        })
        .collect::<Vec<_>>();

    if fresh_requested_venues.is_empty() {
        return CanaryExitPositionFlattenAccountTruthApply {
            fresh_requested_venues,
            position_changed: false,
        };
    }

    let account_apply = apply_account_snapshot_to_state(cfg, snapshot, state, now_ms);
    mark_initialized_account_venues(cfg, snapshot, account_state_initialized, now_ms);
    update_applied_account_position_baselines(
        cfg,
        snapshot,
        applied_account_position_baselines,
        now_ms,
    );

    CanaryExitPositionFlattenAccountTruthApply {
        fresh_requested_venues,
        position_changed: account_apply.position_changed,
    }
}

fn terminal_account_truth_refresh_usable(
    report: &ReconciliationReport,
    account_available: bool,
) -> bool {
    if !account_available {
        return false;
    }
    if report.account_ok {
        return true;
    }
    !report.issues.is_empty()
        && report
            .issues
            .iter()
            .all(|issue| issue == ACCOUNT_SNAPSHOT_SEQ_BEHIND_CACHE_ISSUE)
}

fn apply_terminal_account_truth_refresh(
    cache: &mut LiveStateCache,
    account_snapshot: &super::types::AccountSnapshot,
    report: &ReconciliationReport,
    account_available: bool,
) -> bool {
    if !terminal_account_truth_refresh_usable(report, account_available) {
        return false;
    }
    if report.account_ok {
        return true;
    }
    cache
        .apply_terminal_account_truth_snapshot(account_snapshot)
        .is_ok()
}

async fn refresh_canary_exit_position_flatten_account_truth(
    cfg: &Config,
    state: &mut GlobalState,
    account_tx: Option<&mpsc::Sender<LiveAccountRequest>>,
    cache: &mut LiveStateCache,
    audit_dir: &std::path::Path,
    last_account_snapshot_ms: &mut [Option<TimestampMs>],
    account_state_initialized: &mut [bool],
    applied_account_position_baselines: &mut [Option<f64>],
    venue_indices: &[usize],
    position_tol_tao: f64,
    tick: u64,
    phase: &str,
) -> bool {
    let Some(account_tx) = account_tx else {
        return false;
    };
    if venue_indices.is_empty() {
        return false;
    }

    let now_ms = now_ms();
    let mut refreshed_venues = Vec::new();
    for venue_index in venue_indices.iter().copied() {
        let Some(venue) = cfg.venues.get(venue_index) else {
            continue;
        };
        let timeout_ms = parse_optional_positive_i64_env(
            "PARAPHINA_CANARY_EXIT_POSITION_FLATTEN_ACCOUNT_REFRESH_TIMEOUT_MS",
        )
        .unwrap_or(500)
        .clamp(100, 5_000) as u64;
        let account_snapshot =
            send_account_and_wait(account_tx, venue_index, now_ms, timeout_ms, tick).await;
        let Some(account_snapshot) = account_snapshot else {
            continue;
        };
        if account_snapshot.timestamp_ms > 0 {
            if let Some(last) = last_account_snapshot_ms.get_mut(account_snapshot.venue_index) {
                *last = Some(account_snapshot.timestamp_ms);
            }
        }
        let account_available = account_snapshot_available(cfg, &account_snapshot, now_ms);
        let (report, diff) = cache.reconcile_account_snapshot_with_diff(&account_snapshot);
        if let Some(diff) = diff {
            let _ = append_account_reconcile_audit(audit_dir, now_ms, diff);
        }
        if apply_terminal_account_truth_refresh(
            cache,
            &account_snapshot,
            &report,
            account_available,
        ) {
            if !report.account_ok {
                eprintln!(
                    "[runner] canary_exit_position_flatten_cleanup account_refresh_applied_with_reconcile_mismatch phase={} venue={}",
                    phase, venue.id
                );
            }
            refreshed_venues.push(venue_index);
        } else {
            eprintln!(
                "[runner] canary_exit_position_flatten_cleanup account_refresh_not_fresh phase={} venue={} account_ok={} account_available={}",
                phase, venue.id, report.account_ok, account_available
            );
        }
    }

    if refreshed_venues.is_empty() {
        return false;
    }

    let refreshed_snapshot = cache.snapshot_per_venue(now_ms, &cfg.venues, cfg.book.stale_ms);
    let apply = apply_canary_exit_position_flatten_account_truth_snapshot(
        cfg,
        state,
        &refreshed_snapshot,
        &refreshed_venues,
        now_ms,
        account_state_initialized,
        applied_account_position_baselines,
    );
    if apply.fresh_requested_venues.is_empty() {
        return false;
    }

    let remaining_venues =
        canary_exit_position_flatten_residual_venues(cfg, state, position_tol_tao);
    eprintln!(
        "[runner] canary_exit_position_flatten_cleanup account_refresh_applied phase={} fresh_venues={} position_changed={} remaining_venues={}",
        phase,
        venue_ids_for_indices(cfg, &apply.fresh_requested_venues).join(","),
        apply.position_changed,
        venue_ids_for_indices(cfg, &remaining_venues).join(",")
    );
    true
}

async fn run_canary_exit_position_flatten_cleanup(
    cfg: &Config,
    state: &mut GlobalState,
    priority_order_tx: &mpsc::Sender<LiveOrderRequest>,
    account_tx: Option<&mpsc::Sender<LiveAccountRequest>>,
    cache: &mut LiveStateCache,
    audit_dir: &std::path::Path,
    last_account_snapshot_ms: &mut [Option<TimestampMs>],
    account_state_initialized: &mut [bool],
    applied_account_position_baselines: &mut [Option<f64>],
    phase51_target_key_registry: &mut Phase51TargetKeyRegistry,
    tick: u64,
) {
    let position_tol_tao = canary_exit_position_flatten_tol_tao();
    let attempts = canary_exit_position_flatten_attempts();
    let settle_ms = canary_exit_position_flatten_settle_ms();
    for attempt in 1..=attempts {
        let residual_venues =
            canary_exit_position_flatten_residual_venues(cfg, state, position_tol_tao);
        if residual_venues.is_empty() {
            eprintln!(
                "[runner] canary_exit_position_flatten_cleanup clean attempt={} position_tol_tao={:.6}",
                attempt, position_tol_tao
            );
            return;
        }
        let _ = refresh_canary_exit_position_flatten_account_truth(
            cfg,
            state,
            account_tx,
            cache,
            audit_dir,
            last_account_snapshot_ms,
            account_state_initialized,
            applied_account_position_baselines,
            &residual_venues,
            position_tol_tao,
            tick.saturating_add(attempt as u64),
            "pre_dispatch",
        )
        .await;
        let residual_venues =
            canary_exit_position_flatten_residual_venues(cfg, state, position_tol_tao);
        if residual_venues.is_empty() {
            eprintln!(
                "[runner] canary_exit_position_flatten_cleanup clean_after_account_refresh attempt={}",
                attempt
            );
            return;
        }
        let target_venues = canary_exit_position_flatten_venues(cfg, state, position_tol_tao);
        if target_venues.is_empty() {
            eprintln!(
                "[runner] canary_exit_position_flatten_cleanup blocked attempt={} residual_venues={} position_tol_tao={:.6}",
                attempt,
                venue_ids_for_indices(cfg, &residual_venues).join(","),
                position_tol_tao
            );
        } else {
            eprintln!(
                "[runner] canary_exit_position_flatten_cleanup attempt={} target_venues={} residual_venues={} position_tol_tao={:.6}",
                attempt,
                venue_ids_for_indices(cfg, &target_venues).join(","),
                venue_ids_for_indices(cfg, &residual_venues).join(","),
                position_tol_tao
            );
            let dispatch_tick = tick.saturating_add(attempt as u64);
            let now_ms = now_ms();
            let flatten_intents =
                build_canary_breach_flatten_intents(cfg, state, &target_venues, dispatch_tick);
            if flatten_intents.is_empty() {
                eprintln!(
                    "[runner] canary_exit_position_flatten_cleanup no_flatten_intents attempt={} target_venues={}",
                    attempt,
                    venue_ids_for_indices(cfg, &target_venues).join(",")
                );
            } else {
                let mut flatten_intents = flatten_intents;
                normalize_live_client_order_ids(&mut flatten_intents, dispatch_tick);
                let submitted_venues = venue_indices_for_order_intents(&flatten_intents);
                let action_batch = build_live_action_batch(
                    cfg,
                    &flatten_intents,
                    now_ms,
                    dispatch_tick.saturating_mul(32).saturating_add(63),
                );
                let (outcome, events) = send_order_and_wait_with_status(
                    priority_order_tx,
                    phase51_target_key_registry,
                    flatten_intents,
                    action_batch,
                    now_ms,
                    KILL_FLATTEN_TIMEOUT_MS,
                    TransportHint::Default,
                    "canary_exit_position_flatten",
                    dispatch_tick,
                )
                .await;
                let submitted = !matches!(outcome, OrderWaitOutcomeKind::ChannelFull);
                let mut accepted_venues = Vec::new();
                if let Some(events) = events {
                    for event in &events {
                        if let super::types::ExecutionEvent::OrderAccepted(ack) = event {
                            if !accepted_venues.contains(&ack.venue_index) {
                                accepted_venues.push(ack.venue_index);
                            }
                        }
                    }
                    let core_events = live_events_to_core(&events);
                    let fills = apply_execution_events(state, &core_events, now_ms);
                    if !fills.is_empty() {
                        apply_live_fills(cfg, state, &fills, now_ms);
                        state.recompute_after_fills(cfg);
                    }
                }
                eprintln!(
                    "[runner] canary_exit_position_flatten_cleanup dispatched attempt={} outcome={:?} submitted={} submitted_venues={} accepted_venues={}",
                    attempt,
                    outcome,
                    submitted,
                    venue_ids_for_indices(cfg, &submitted_venues).join(","),
                    venue_ids_for_indices(cfg, &accepted_venues).join(",")
                );
            }
        }
        let remaining_venues =
            canary_exit_position_flatten_residual_venues(cfg, state, position_tol_tao);
        if remaining_venues.is_empty() {
            eprintln!(
                "[runner] canary_exit_position_flatten_cleanup clean_after_dispatch attempt={}",
                attempt
            );
            return;
        }
        let _ = refresh_canary_exit_position_flatten_account_truth(
            cfg,
            state,
            account_tx,
            cache,
            audit_dir,
            last_account_snapshot_ms,
            account_state_initialized,
            applied_account_position_baselines,
            &remaining_venues,
            position_tol_tao,
            tick.saturating_add(50).saturating_add(attempt as u64),
            "post_dispatch",
        )
        .await;
        let remaining_venues =
            canary_exit_position_flatten_residual_venues(cfg, state, position_tol_tao);
        if remaining_venues.is_empty() {
            eprintln!(
                "[runner] canary_exit_position_flatten_cleanup clean_after_account_refresh attempt={}",
                attempt
            );
            return;
        }
        if settle_ms > 0 && attempt < attempts {
            tokio::time::sleep(Duration::from_millis(settle_ms)).await;
        }
    }
    let mut remaining_venues =
        canary_exit_position_flatten_residual_venues(cfg, state, position_tol_tao);
    let _ = refresh_canary_exit_position_flatten_account_truth(
        cfg,
        state,
        account_tx,
        cache,
        audit_dir,
        last_account_snapshot_ms,
        account_state_initialized,
        applied_account_position_baselines,
        &remaining_venues,
        position_tol_tao,
        tick.saturating_add(500),
        "final_check",
    )
    .await;
    remaining_venues = canary_exit_position_flatten_residual_venues(cfg, state, position_tol_tao);
    if remaining_venues.is_empty() {
        eprintln!(
            "[runner] canary_exit_position_flatten_cleanup clean_after_final_account_refresh"
        );
        return;
    }
    eprintln!(
        "[runner] canary_exit_position_flatten_cleanup incomplete residual_venues={} position_tol_tao={:.6}",
        venue_ids_for_indices(cfg, &remaining_venues).join(","),
        position_tol_tao
    );
    mark_canary_exit_position_flatten_incomplete(state);
}

fn canary_exit_cancel_all_sweep_all_venues_enabled() -> bool {
    parse_bool_env_default("PARAPHINA_CANARY_EXIT_CANCEL_ALL_SWEEP_ALL_VENUES", false)
}

fn terminal_residual_convergence_venue_indices(
    cfg: &Config,
    config: &TerminalResidualConvergenceConfig,
) -> HashSet<usize> {
    if !config.account_refresh_enabled && !config.reduce_after_cancel_confirm_enabled {
        return HashSet::new();
    }
    cfg.venues
        .iter()
        .enumerate()
        .filter_map(|(venue_index, venue)| {
            config
                .venue_ids
                .contains(&venue.id.to_ascii_lowercase())
                .then_some(venue_index)
        })
        .collect()
}

fn startup_pnl_baseline_config_from_env(canary_enabled: bool) -> StartupPnlBaselineConfig {
    if !canary_enabled {
        return StartupPnlBaselineConfig::default();
    }
    StartupPnlBaselineConfig {
        enabled: std::env::var("PARAPHINA_CANARY_STARTUP_PNL_BASELINE_GUARD")
            .map(|v| v != "0" && !v.eq_ignore_ascii_case("false"))
            .unwrap_or(true),
        pnl_abs_limit_usd: parse_optional_positive_f64_env(
            "PARAPHINA_CANARY_STARTUP_PNL_LIMIT_USD",
        )
        .unwrap_or(1.0),
        position_tol_tao: parse_optional_positive_f64_env(
            "PARAPHINA_CANARY_STARTUP_POSITION_TAO_TOL",
        )
        .unwrap_or(0.0025),
        max_wait_ticks: std::env::var("PARAPHINA_CANARY_STARTUP_PNL_MAX_WAIT_TICKS")
            .ok()
            .and_then(|v| v.parse::<u64>().ok())
            .filter(|v| *v > 0)
            .unwrap_or(40),
        require_full_account_coverage: std::env::var(
            "PARAPHINA_CANARY_STARTUP_REQUIRE_FULL_ACCOUNT_COVERAGE",
        )
        .map(|v| v != "0" && !v.eq_ignore_ascii_case("false"))
        .unwrap_or(false),
    }
}

fn startup_stale_arming_ms_from_env(canary_enabled: bool) -> TimestampMs {
    if !canary_enabled {
        return 0;
    }
    parse_optional_positive_i64_env("PARAPHINA_STARTUP_STALE_ARMING_MS").unwrap_or(4_000)
}

fn startup_stale_pending_venues(snapshot: &CanonicalCacheSnapshot) -> Vec<String> {
    snapshot
        .market
        .iter()
        .filter(|market| market.mid.is_none() || market.is_stale)
        .map(|market| market.venue_id.to_string())
        .collect()
}

fn evaluate_startup_stale_arming(
    snapshot: &CanonicalCacheSnapshot,
    now_ms: TimestampMs,
    startup_started_ms: TimestampMs,
    startup_arming_ms: TimestampMs,
    armed_before_tick: bool,
) -> StartupStaleArmingStatus {
    let enabled = startup_arming_ms > 0;
    let elapsed_ms = now_ms.saturating_sub(startup_started_ms).max(0);
    let pending_venues = startup_stale_pending_venues(snapshot);
    let all_ready = pending_venues.is_empty();
    let armed_this_tick = enabled && !armed_before_tick && elapsed_ms >= startup_arming_ms;
    let armed = !enabled || armed_before_tick || armed_this_tick;
    let arm_reason = if !enabled {
        Some("disabled".to_string())
    } else if armed {
        Some(
            if all_ready {
                "all_ready_after_min"
            } else {
                "timeout"
            }
            .to_string(),
        )
    } else {
        None
    };
    StartupStaleArmingStatus {
        enabled,
        armed,
        armed_this_tick,
        elapsed_ms,
        arming_ms: startup_arming_ms,
        pending_venues,
        arm_reason,
    }
}

fn inventory_brake_fractions_from_env() -> InventoryBrakeFractions {
    let default_fraction =
        parse_optional_fraction_env("PARAPHINA_CANARY_INVENTORY_BRAKE_FRACTION").unwrap_or(0.75);
    InventoryBrakeFractions {
        net_fraction: Some(
            parse_optional_fraction_env("PARAPHINA_CANARY_INVENTORY_BRAKE_NET_FRACTION")
                .unwrap_or(default_fraction),
        ),
        gross_fraction: Some(
            parse_optional_fraction_env("PARAPHINA_CANARY_INVENTORY_BRAKE_GROSS_FRACTION")
                .unwrap_or(default_fraction),
        ),
        venue_fraction: Some(
            parse_optional_fraction_env("PARAPHINA_CANARY_INVENTORY_BRAKE_VENUE_FRACTION")
                .unwrap_or(default_fraction),
        ),
    }
}

fn inventory_brake_limits(
    max_position_tao: Option<f64>,
    max_gross_position_tao: Option<f64>,
    max_abs_venue_position_tao: Option<f64>,
    fractions: InventoryBrakeFractions,
) -> InventoryBrakeLimits {
    InventoryBrakeLimits {
        max_position_tao: max_position_tao
            .zip(fractions.net_fraction)
            .map(|(limit, fraction)| (limit * fraction).max(0.0)),
        max_gross_position_tao: max_gross_position_tao
            .zip(fractions.gross_fraction)
            .map(|(limit, fraction)| (limit * fraction).max(0.0)),
        max_abs_venue_position_tao: max_abs_venue_position_tao
            .zip(fractions.venue_fraction)
            .map(|(limit, fraction)| (limit * fraction).max(0.0)),
    }
}

fn side_increases_abs_position(side: Side, position_tao: f64) -> bool {
    match position_tao.partial_cmp(&0.0).unwrap_or(Ordering::Equal) {
        Ordering::Greater => matches!(side, Side::Buy),
        Ordering::Less => matches!(side, Side::Sell),
        Ordering::Equal => true,
    }
}

fn push_reason(reasons: &mut Vec<String>, reason: &'static str) {
    if !reasons.iter().any(|existing| existing == reason) {
        reasons.push(reason.to_string());
    }
}

fn apply_inventory_soft_governor(
    state: &GlobalState,
    quotes: &mut [crate::mm::MmQuote],
    limits: SoftInventoryGovernorLimits,
) -> InventorySoftGovernorStatus {
    let q_gross_tao = gross_position_tao(state);
    let q_max_abs_venue_tao = max_abs_venue_position_tao(state);
    let mut status = InventorySoftGovernorStatus {
        configured: limits.configured(),
        triggered: false,
        max_position_tao: limits.max_position_tao,
        max_gross_position_tao: limits.max_gross_position_tao,
        max_abs_venue_position_tao: limits.max_abs_venue_position_tao,
        q_global_tao: state.q_global_tao,
        q_gross_tao,
        q_max_abs_venue_tao,
        global_reasons: Vec::new(),
        blocked_venues: Vec::new(),
    };

    if !status.configured {
        return status;
    }

    let net_long_breach = limits
        .max_position_tao
        .is_some_and(|limit| state.q_global_tao >= limit);
    let net_short_breach = limits
        .max_position_tao
        .is_some_and(|limit| state.q_global_tao <= -limit);
    let gross_breach = limits
        .max_gross_position_tao
        .is_some_and(|limit| q_gross_tao >= limit);

    if net_long_breach {
        status.global_reasons.push("net_long_soft_cap".to_string());
    }
    if net_short_breach {
        status.global_reasons.push("net_short_soft_cap".to_string());
    }
    if gross_breach {
        status.global_reasons.push("gross_soft_cap".to_string());
    }

    for quote in quotes.iter_mut() {
        let Some(venue_state) = state.venues.get(quote.venue_index) else {
            continue;
        };
        let position_tao = venue_state.position_tao;
        let venue_breach = limits
            .max_abs_venue_position_tao
            .is_some_and(|limit| position_tao.abs() >= limit);
        let mut bid_reasons = Vec::new();
        let mut ask_reasons = Vec::new();

        if gross_breach {
            if quote.bid.is_some() && side_increases_abs_position(Side::Buy, position_tao) {
                push_reason(&mut bid_reasons, "gross_soft_cap");
            }
            if quote.ask.is_some() && side_increases_abs_position(Side::Sell, position_tao) {
                push_reason(&mut ask_reasons, "gross_soft_cap");
            }
        }
        if net_long_breach && quote.bid.is_some() {
            push_reason(&mut bid_reasons, "net_long_soft_cap");
        }
        if net_short_breach && quote.ask.is_some() {
            push_reason(&mut ask_reasons, "net_short_soft_cap");
        }
        if venue_breach {
            if quote.bid.is_some() && side_increases_abs_position(Side::Buy, position_tao) {
                push_reason(&mut bid_reasons, "venue_soft_cap");
            }
            if quote.ask.is_some() && side_increases_abs_position(Side::Sell, position_tao) {
                push_reason(&mut ask_reasons, "venue_soft_cap");
            }
        }

        let blocked_bid = !bid_reasons.is_empty();
        let blocked_ask = !ask_reasons.is_empty();
        if blocked_bid && quote.bid.is_some() {
            quote.bid = None;
            quote.bid_terminal_reason = "inventory_soft_governor_suppressed";
        }
        if blocked_ask && quote.ask.is_some() {
            quote.ask = None;
            quote.ask_terminal_reason = "inventory_soft_governor_suppressed";
        }
        if blocked_bid || blocked_ask {
            status
                .blocked_venues
                .push(InventorySoftGovernorVenueStatus {
                    venue_index: quote.venue_index,
                    venue_id: quote.venue_id.to_string(),
                    position_tao,
                    blocked_bid,
                    blocked_ask,
                    bid_reasons,
                    ask_reasons,
                });
        }
    }

    status.triggered = !status.global_reasons.is_empty() || !status.blocked_venues.is_empty();
    status
}

fn signed_fill_delta_tao(side: Side, size: f64) -> f64 {
    match side {
        Side::Buy => size,
        Side::Sell => -size,
    }
}

fn soft_unwind_has_material_positions(cfg: &Config, state: &GlobalState) -> bool {
    state.venues.iter().enumerate().any(|(venue_index, venue)| {
        venue.position_tao.abs()
            >= cfg
                .venues
                .get(venue_index)
                .map(|cfg| cfg.lot_size_tao.max(1e-9))
                .unwrap_or(1e-9)
    })
}

fn snap_size_down_to_lot(size: f64, lot_size: f64) -> f64 {
    if !size.is_finite() || !lot_size.is_finite() || lot_size <= 0.0 {
        return 0.0;
    }
    let lots = (size / lot_size).floor();
    if !lots.is_finite() || lots <= 0.0 {
        0.0
    } else {
        lots * lot_size
    }
}

fn venue_min_executable_order_size_tao(venue: &crate::config::VenueConfig) -> f64 {
    venue.size_step_tao.max(venue.lot_size_tao).max(1e-9)
}

fn fresh_account_or_state_position_tao(
    cfg: &Config,
    state: &GlobalState,
    snapshot: &CanonicalCacheSnapshot,
    venue_index: usize,
    now_ms: TimestampMs,
) -> f64 {
    snapshot
        .account
        .get(venue_index)
        .filter(|acct| {
            account_cache_snapshot_fresh(
                acct,
                now_ms,
                account_snapshot_max_age_ms_for_venue(cfg, acct.venue_id.as_ref()),
            )
        })
        .map(|acct| acct.position_tao)
        .unwrap_or_else(|| {
            state
                .venues
                .get(venue_index)
                .map(|venue| venue.position_tao)
                .unwrap_or_default()
        })
}

fn fresh_account_position_tao(
    cfg: &Config,
    snapshot: &CanonicalCacheSnapshot,
    venue_index: usize,
    now_ms: TimestampMs,
) -> Option<f64> {
    snapshot
        .account
        .get(venue_index)
        .filter(|acct| {
            account_cache_snapshot_fresh(
                acct,
                now_ms,
                account_snapshot_max_age_ms_for_venue(cfg, acct.venue_id.as_ref()),
            )
        })
        .map(|acct| acct.position_tao)
}

fn lighter_orderly_exit_residual_position_tao(
    cfg: &Config,
    state: &GlobalState,
    snapshot: &CanonicalCacheSnapshot,
    venue_index: usize,
    now_ms: TimestampMs,
    position_tol_tao: f64,
    allow_live_orders: bool,
) -> Option<f64> {
    let venue_cfg = cfg.venues.get(venue_index)?;
    if !venue_cfg.id.eq_ignore_ascii_case("lighter") {
        return None;
    }
    let venue = state.venues.get(venue_index)?;
    if venue.status != VenueStatus::Healthy {
        return None;
    }
    if live_open_order_count_for_venue(state, venue_index) != 0 && !allow_live_orders {
        return None;
    }
    let account_position_tao = fresh_account_position_tao(cfg, snapshot, venue_index, now_ms)?;
    if !account_position_tao.is_finite() {
        return None;
    }
    let lot_size = venue_cfg.lot_size_tao.max(1e-9);
    let position_abs = account_position_tao.abs();
    let position_tol = position_tol_tao.max(0.0025).min(lot_size);
    if position_abs <= position_tol + 1e-9 || position_abs + 1e-9 >= lot_size {
        return None;
    }
    Some(account_position_tao)
}

fn has_lighter_orderly_exit_residual_convergence(
    cfg: &Config,
    state: &GlobalState,
    snapshot: &CanonicalCacheSnapshot,
    now_ms: TimestampMs,
    position_tol_tao: f64,
) -> bool {
    (0..state.venues.len()).any(|venue_index| {
        lighter_orderly_exit_residual_position_tao(
            cfg,
            state,
            snapshot,
            venue_index,
            now_ms,
            position_tol_tao,
            false,
        )
        .is_some()
    })
}

fn evaluate_startup_pnl_baseline(
    cfg: &Config,
    state: &GlobalState,
    snapshot: &CanonicalCacheSnapshot,
    account_state_initialized: &[bool],
    now_ms: TimestampMs,
    waited_ticks: u64,
    guard_cfg: StartupPnlBaselineConfig,
) -> StartupPnlBaselineStatus {
    let required_venue_ids =
        startup_pnl_baseline_required_venue_ids_for_ranked_execution_canary(cfg);
    let required_account_count = cfg
        .venues
        .iter()
        .filter(|venue| {
            required_venue_ids.as_ref().map_or(true, |required| {
                required.contains(&venue.id.to_ascii_lowercase())
            })
        })
        .count();
    let mut status = StartupPnlBaselineStatus {
        enabled: guard_cfg.enabled,
        waited_ticks,
        max_wait_ticks: guard_cfg.max_wait_ticks,
        require_full_account_coverage: guard_cfg.require_full_account_coverage,
        pnl_abs_limit_usd: guard_cfg.pnl_abs_limit_usd,
        position_tol_tao: guard_cfg.position_tol_tao,
        daily_realised_pnl: state.daily_realised_pnl,
        daily_unrealised_pnl: state.daily_unrealised_pnl,
        daily_pnl_total: state.daily_pnl_total,
        required_account_count,
        ..StartupPnlBaselineStatus::default()
    };
    if !guard_cfg.enabled {
        return status;
    }
    if required_venue_ids.is_some() && status.required_account_count == 0 {
        status.triggered = true;
        status.reason = Some("startup_baseline_no_required_execution_venues".to_string());
        return status;
    }

    let fair_value = state
        .fair_value
        .filter(|value| value.is_finite() && *value > 0.0);
    let mut pending_venues = Vec::new();
    let mut fresh_account_count = 0usize;
    let mut violating_venues = Vec::new();
    let mut positioned_without_fair_value = Vec::new();

    for (venue_index, venue_cfg) in cfg.venues.iter().enumerate() {
        if required_venue_ids
            .as_ref()
            .is_some_and(|required| !required.contains(&venue_cfg.id.to_ascii_lowercase()))
        {
            continue;
        }
        let acct = snapshot.account.get(venue_index);
        let fresh = acct
            .filter(|acct| {
                account_cache_snapshot_fresh(
                    acct,
                    now_ms,
                    account_snapshot_max_age_ms_for_venue(cfg, acct.venue_id.as_ref()),
                )
            })
            .is_some();
        if fresh && venue_state_initialized(account_state_initialized, venue_index) {
            fresh_account_count += 1;
        } else {
            pending_venues.push(venue_cfg.id.clone());
        }
        let Some(acct) = acct else {
            continue;
        };
        if !fresh {
            continue;
        }
        if fair_value.is_none() && acct.position_tao.abs() > 1e-12 {
            positioned_without_fair_value.push(venue_cfg.id.clone());
            continue;
        }
        let fair_value = fair_value.unwrap_or(acct.avg_entry_price.max(1.0));
        let unrealised_pnl_usd = acct.position_tao * (fair_value - acct.avg_entry_price);
        let position_breach = acct.position_tao.abs() > guard_cfg.position_tol_tao;
        if position_breach || unrealised_pnl_usd <= -guard_cfg.pnl_abs_limit_usd {
            violating_venues.push(StartupPnlBaselineVenueStatus {
                venue_index,
                venue_id: acct.venue_id.to_string(),
                position_tao: acct.position_tao,
                avg_entry_price: acct.avg_entry_price,
                fair_value,
                unrealised_pnl_usd,
                position_breach,
            });
        }
    }

    status.fresh_account_count = fresh_account_count;
    status.pending_venues = pending_venues;
    status.violating_venues = violating_venues;

    let full_account_coverage = fresh_account_count >= status.required_account_count;
    if !positioned_without_fair_value.is_empty() {
        status.waiting_for_accounts = true;
        status.pending_venues = positioned_without_fair_value;
        if waited_ticks >= guard_cfg.max_wait_ticks {
            status.triggered = true;
            status.timed_out = true;
            status.reason = Some("awaiting_fair_value_timeout".to_string());
        } else {
            status.reason = Some("awaiting_fair_value".to_string());
        }
        return status;
    }
    let partial_account_coverage_timed_out = !guard_cfg.require_full_account_coverage
        && !full_account_coverage
        && waited_ticks >= guard_cfg.max_wait_ticks
        && fresh_account_count > 0;
    if !full_account_coverage && !partial_account_coverage_timed_out {
        status.waiting_for_accounts = true;
        if waited_ticks >= guard_cfg.max_wait_ticks {
            status.triggered = true;
            status.timed_out = true;
            status.reason = Some("awaiting_account_snapshots_timeout".to_string());
        } else {
            status.reason = Some("awaiting_account_snapshots".to_string());
        }
        return status;
    }

    if state.daily_pnl_total <= -guard_cfg.pnl_abs_limit_usd {
        status.triggered = true;
        status.reason = Some("startup_inherited_pnl_breach".to_string());
        return status;
    }

    if !status.violating_venues.is_empty() {
        status.triggered = true;
        status.reason = Some("startup_position_baseline_breach".to_string());
        return status;
    }

    status.resolved = true;
    status.passed = true;
    status.reason = Some(if partial_account_coverage_timed_out {
        "startup_baseline_partial_account_coverage_ok".to_string()
    } else {
        "startup_baseline_ok".to_string()
    });
    status
}

fn clamp_confirmed_reduce_only_target_position_tao(
    cfg: &Config,
    state: &GlobalState,
    snapshot: &CanonicalCacheSnapshot,
    venue_index: usize,
    now_ms: TimestampMs,
    target_position_tao: f64,
    treat_live_orders_as_cancelling: bool,
    class: EmergencyRequestClass,
    mut residual_fallback: Option<&mut EmergencyResidualFallbackStatus>,
) -> Option<f64> {
    let venue = cfg.venues.get(venue_index)?;
    let lot_size = venue.lot_size_tao.max(1e-9);
    let min_order_size = if venue.id.eq_ignore_ascii_case("aster") {
        venue_min_executable_order_size_tao(venue)
    } else {
        lot_size
    };
    let live_open_order_count = live_open_order_count_for_venue(state, venue_index);
    let has_live_orders = live_open_order_count > 0 && !treat_live_orders_as_cancelling;
    let mut used_state_fallback = false;
    let account_position_tao = if let Some(account_position_tao) =
        fresh_account_position_tao(cfg, snapshot, venue_index, now_ms)
    {
        Some(account_position_tao)
    } else if venue.id.eq_ignore_ascii_case("lighter") {
        if has_live_orders {
            None
        } else {
            let state_position_tao = state.venues.get(venue_index)?.position_tao;
            let confirmed_abs = snap_size_down_to_lot(state_position_tao.abs(), lot_size);
            let max_fallback_abs = snap_size_down_to_lot(lot_size * 4.0, lot_size);
            if confirmed_abs < lot_size || confirmed_abs > max_fallback_abs {
                None
            } else {
                Some(state_position_tao.signum() * confirmed_abs)
            }
        }
    } else {
        used_state_fallback = true;
        bounded_state_fallback_position_tao(
            cfg,
            state,
            venue_index,
            target_position_tao,
            live_open_order_count,
            min_order_size,
            treat_live_orders_as_cancelling,
            class,
            residual_fallback.as_mut().map(|status| &mut **status),
        )
    }?;
    if account_position_tao.abs() < min_order_size {
        if venue.id.eq_ignore_ascii_case("aster") && account_position_tao.abs() >= lot_size {
            push_emergency_residual_fallback_record(
                residual_fallback.as_mut().map(|status| &mut **status),
                class,
                venue_index,
                venue.id.as_str(),
                EmergencyResidualFallbackDecision::Rejected,
                EmergencyResidualFallbackReason::BelowSizeStep,
                account_position_tao,
                account_position_tao.abs(),
            );
        }
        return None;
    }
    if target_position_tao.signum() == 0.0
        || account_position_tao.signum() != target_position_tao.signum()
    {
        return None;
    }
    let confirmed_abs = snap_size_down_to_lot(account_position_tao.abs(), min_order_size);
    if confirmed_abs < min_order_size {
        return None;
    }
    // Reduce-only emergency hedges must only target confirmed same-side inventory.
    // Aster keeps an extra one-lot haircut by default because its account stream can
    // still lag just enough around the emergency path that a full-size reduce_only
    // IOC gets rejected after the first partial flatten. The exact two-lot terminal
    // residual case is reversible/env-gated and only bypasses the haircut once live
    // orders are already gone.
    let max_send_abs = if venue.id.eq_ignore_ascii_case("aster") {
        let max_full_target_abs = snap_size_down_to_lot(
            min_order_size * aster_soft_unwind_full_target_max_lots(),
            min_order_size,
        );
        if (confirmed_abs <= min_order_size + 1e-9 && !has_live_orders)
            || (live_open_order_count == 0 && confirmed_abs <= max_full_target_abs + 1e-9)
        {
            confirmed_abs
        } else {
            snap_size_down_to_lot((confirmed_abs - min_order_size).max(0.0), min_order_size)
        }
    } else if treat_live_orders_as_cancelling
        && !(used_state_fallback
            && venue.id.eq_ignore_ascii_case("extended")
            && extended_state_fallback_step_lots().is_some())
    {
        // When same-side live orders are already being canceled, allow one extra lot
        // so a last worsening maker fill racing the cancel can still be flattened in
        // the same emergency path. Do not re-expand env-stepped Extended fallback
        // when account truth is stale; that path is deliberately one-step to avoid
        // reduce-only size conflicts against venue-truth position.
        snap_size_down_to_lot(confirmed_abs + lot_size, lot_size)
    } else {
        confirmed_abs
    };
    if max_send_abs < min_order_size {
        return None;
    }
    let clamped_abs = target_position_tao.abs().min(max_send_abs);
    if clamped_abs < min_order_size {
        if venue.id.eq_ignore_ascii_case("aster") && clamped_abs >= lot_size {
            push_emergency_residual_fallback_record(
                residual_fallback.as_mut().map(|status| &mut **status),
                class,
                venue_index,
                venue.id.as_str(),
                EmergencyResidualFallbackDecision::Rejected,
                EmergencyResidualFallbackReason::BelowSizeStep,
                account_position_tao,
                clamped_abs,
            );
        }
        return None;
    }
    Some(target_position_tao.signum() * clamped_abs)
}

fn push_emergency_residual_fallback_record(
    residual_fallback: Option<&mut EmergencyResidualFallbackStatus>,
    class: EmergencyRequestClass,
    venue_index: usize,
    venue_id: &str,
    status: EmergencyResidualFallbackDecision,
    reason: EmergencyResidualFallbackReason,
    state_position_tao: f64,
    clamped_size_tao: f64,
) {
    let Some(residual_fallback) = residual_fallback else {
        return;
    };
    residual_fallback
        .records
        .push(EmergencyResidualFallbackRecord {
            class,
            venue_index,
            venue_id: venue_id.to_string(),
            status,
            reason,
            state_position_tao,
            clamped_size_tao,
        });
}

fn bounded_state_fallback_position_tao(
    cfg: &Config,
    state: &GlobalState,
    venue_index: usize,
    target_position_tao: f64,
    live_open_order_count: usize,
    lot_size: f64,
    treat_live_orders_as_cancelling: bool,
    class: EmergencyRequestClass,
    residual_fallback: Option<&mut EmergencyResidualFallbackStatus>,
) -> Option<f64> {
    let venue = cfg.venues.get(venue_index)?;
    let aster_soft_unwind_fallback = venue.id.eq_ignore_ascii_case("aster")
        && matches!(class, EmergencyRequestClass::SoftUnwind);
    if !venue.id.eq_ignore_ascii_case("extended")
        && !venue.id.eq_ignore_ascii_case("paradex")
        && !aster_soft_unwind_fallback
    {
        return None;
    }
    let state_position_tao = state.venues.get(venue_index)?.position_tao;
    if live_open_order_count > 0 && !treat_live_orders_as_cancelling {
        push_emergency_residual_fallback_record(
            residual_fallback,
            class,
            venue_index,
            venue.id.as_str(),
            EmergencyResidualFallbackDecision::Rejected,
            EmergencyResidualFallbackReason::LiveOrdersPresent,
            state_position_tao,
            0.0,
        );
        return None;
    }
    let confirmed_abs = snap_size_down_to_lot(state_position_tao.abs(), lot_size);
    if confirmed_abs < lot_size {
        return None;
    }
    let max_fallback_lots = if aster_soft_unwind_fallback {
        // Aster user/account updates can lag a just-acked cancel_all. Permit the
        // exact observed post-cancel residual class without widening hard caps.
        2.0
    } else if venue.id.eq_ignore_ascii_case("extended")
        && matches!(class, EmergencyRequestClass::SoftUnwind)
    {
        extended_soft_unwind_state_fallback_max_lots()
    } else if venue.id.eq_ignore_ascii_case("paradex")
        || (venue.id.eq_ignore_ascii_case("extended")
            && matches!(class, EmergencyRequestClass::InventoryBrake))
    {
        3.0
    } else {
        1.0
    };
    let max_fallback_abs = snap_size_down_to_lot(lot_size * max_fallback_lots, lot_size);
    if confirmed_abs > max_fallback_abs + 1e-9 {
        push_emergency_residual_fallback_record(
            residual_fallback,
            class,
            venue_index,
            venue.id.as_str(),
            EmergencyResidualFallbackDecision::Rejected,
            if max_fallback_lots <= 1.0 {
                EmergencyResidualFallbackReason::NotExactOneLot
            } else {
                EmergencyResidualFallbackReason::FallbackSizeTooLarge
            },
            state_position_tao,
            confirmed_abs,
        );
        return None;
    }
    let clamped_abs = target_position_tao.abs().min(confirmed_abs);
    if clamped_abs > max_fallback_abs + 1e-9 {
        push_emergency_residual_fallback_record(
            residual_fallback,
            class,
            venue_index,
            venue.id.as_str(),
            EmergencyResidualFallbackDecision::Rejected,
            EmergencyResidualFallbackReason::FallbackSizeTooLarge,
            state_position_tao,
            clamped_abs,
        );
        return None;
    }
    let clamped_abs = if venue.id.eq_ignore_ascii_case("extended") {
        if let Some(step_lots) = extended_state_fallback_step_lots() {
            clamped_abs.min(snap_size_down_to_lot(lot_size * step_lots, lot_size))
        } else {
            clamped_abs
        }
    } else {
        clamped_abs
    };
    if target_position_tao.signum() == 0.0
        || state_position_tao.signum() != target_position_tao.signum()
    {
        push_emergency_residual_fallback_record(
            residual_fallback,
            class,
            venue_index,
            venue.id.as_str(),
            EmergencyResidualFallbackDecision::Rejected,
            EmergencyResidualFallbackReason::SignMismatch,
            state_position_tao,
            clamped_abs,
        );
        return None;
    }
    if clamped_abs < lot_size {
        push_emergency_residual_fallback_record(
            residual_fallback,
            class,
            venue_index,
            venue.id.as_str(),
            EmergencyResidualFallbackDecision::Rejected,
            EmergencyResidualFallbackReason::NotExactOneLot,
            state_position_tao,
            clamped_abs,
        );
        return None;
    }
    push_emergency_residual_fallback_record(
        residual_fallback,
        class,
        venue_index,
        venue.id.as_str(),
        EmergencyResidualFallbackDecision::Used,
        EmergencyResidualFallbackReason::NoFreshAccount,
        state_position_tao,
        clamped_abs,
    );
    Some(state_position_tao.signum() * clamped_abs)
}

fn is_benign_reduce_only_reject(reject: &OrderReject) -> bool {
    reject.venue_id.eq_ignore_ascii_case("aster")
        && reject.reduce_only == Some(true)
        && matches!(
            reject.purpose,
            Some(OrderPurpose::Hedge) | Some(OrderPurpose::Exit)
        )
        && reject.reason.contains("ReduceOnly Order is rejected")
}

fn soft_unwind_target_position_tao(
    cfg: &Config,
    state: &GlobalState,
    snapshot: &CanonicalCacheSnapshot,
    venue_index: usize,
    now_ms: TimestampMs,
) -> f64 {
    let min_order_size = cfg
        .venues
        .get(venue_index)
        .map(venue_min_executable_order_size_tao)
        .unwrap_or(1e-9);
    let position_source =
        fresh_account_or_state_position_tao(cfg, state, snapshot, venue_index, now_ms);
    let snapped_abs = snap_size_down_to_lot(position_source.abs(), min_order_size);
    if snapped_abs < min_order_size {
        return 0.0;
    }
    if cfg
        .venues
        .get(venue_index)
        .map(|venue| venue.id.eq_ignore_ascii_case("extended"))
        .unwrap_or(false)
    {
        let max_full_target_abs = snap_size_down_to_lot(
            min_order_size * extended_soft_unwind_state_fallback_max_lots(),
            min_order_size,
        );
        if snapped_abs <= max_full_target_abs + 1e-9 {
            return position_source.signum() * snapped_abs;
        }
    }
    if cfg
        .venues
        .get(venue_index)
        .map(|venue| venue.id.eq_ignore_ascii_case("aster"))
        .unwrap_or(false)
    {
        let max_full_target_abs = snap_size_down_to_lot(
            min_order_size * aster_soft_unwind_full_target_max_lots(),
            min_order_size,
        );
        if snapped_abs <= max_full_target_abs + 1e-9 {
            return position_source.signum() * snapped_abs;
        }
    }
    let conservative_abs = if snapped_abs > min_order_size {
        snap_size_down_to_lot(snapped_abs - min_order_size, min_order_size).max(min_order_size)
    } else {
        snapped_abs
    };
    position_source.signum() * conservative_abs
}

fn inventory_brake_target_position_tao(
    cfg: &Config,
    state: &GlobalState,
    snapshot: &CanonicalCacheSnapshot,
    venue_index: usize,
    now_ms: TimestampMs,
) -> f64 {
    let min_order_size = cfg
        .venues
        .get(venue_index)
        .map(venue_min_executable_order_size_tao)
        .unwrap_or(1e-9);
    let position_source =
        fresh_account_or_state_position_tao(cfg, state, snapshot, venue_index, now_ms);
    let projected_position_source = projected_worsening_position_tao(state, venue_index);
    // Size the brake to the live projected same-side exposure so a last worsening fill racing
    // the cancel does not leave the venue one lot beyond the hard cap.
    let target_position_source = if position_source.signum() != 0.0
        && projected_position_source.signum() == position_source.signum()
        && projected_position_source.abs() > position_source.abs()
    {
        projected_position_source
    } else {
        position_source
    };
    let snapped_abs = snap_size_down_to_lot(target_position_source.abs(), min_order_size);
    if snapped_abs < min_order_size {
        return 0.0;
    }
    target_position_source.signum() * snapped_abs
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct SoftUnwindRuntimeState {
    pause_mm_quotes: bool,
    send_unwind: bool,
    refresh_cooldown: bool,
}

fn soft_unwind_runtime_state(
    soft_limit_triggered: bool,
    cooldown_active: bool,
    response_backoff_active: bool,
    has_material_positions: bool,
    has_live_mm_orders: bool,
    orderly_exit_residual_convergence_needed: bool,
    terminal_exit_quiesce_active: bool,
) -> SoftUnwindRuntimeState {
    let send_unwind = !response_backoff_active
        && (((soft_limit_triggered || cooldown_active)
            && (has_material_positions || has_live_mm_orders))
            || orderly_exit_residual_convergence_needed);
    SoftUnwindRuntimeState {
        pause_mm_quotes: soft_limit_triggered
            || cooldown_active
            || response_backoff_active
            || orderly_exit_residual_convergence_needed
            || terminal_exit_quiesce_active,
        send_unwind,
        refresh_cooldown: soft_limit_triggered,
    }
}

fn inventory_brake_requires_mm_pause(status: &InventoryBrakeStatus) -> bool {
    if !status.triggered {
        return false;
    }
    let has_actual_global_exposure = status.q_global_tao.abs() > 1e-9
        || status.q_gross_tao.abs() > 1e-9
        || status.q_max_abs_venue_tao.abs() > 1e-9;
    let has_positioned_blocked_venue = status
        .blocked_venues
        .iter()
        .any(|venue| venue.position_tao.abs() > 1e-9);
    let has_non_projected_reason = status
        .global_reasons
        .iter()
        .any(|reason| !reason.starts_with("projected_"));
    has_actual_global_exposure || has_positioned_blocked_venue || has_non_projected_reason
}

fn inventory_brake_cancel_only_mm_mode(status: &InventoryBrakeStatus) -> bool {
    status.triggered && !inventory_brake_requires_mm_pause(status)
}

fn inventory_brake_waits_for_responses(status: &InventoryBrakeStatus) -> bool {
    inventory_brake_requires_mm_pause(status)
}

fn effective_inventory_brake_intents(
    status: &InventoryBrakeStatus,
    intents: Vec<OrderIntent>,
) -> Vec<OrderIntent> {
    if inventory_brake_cancel_only_mm_mode(status) {
        retain_cancel_only_intents(intents)
    } else {
        intents
    }
}

fn retain_cancel_only_intents(intents: Vec<OrderIntent>) -> Vec<OrderIntent> {
    intents
        .into_iter()
        .filter(|intent| matches!(intent, OrderIntent::Cancel(_)))
        .collect()
}

fn mm_submission_intents_for_quote_gate(
    should_quote: bool,
    pause_mm_quotes: bool,
    inventory_brake_cancel_only_mode: bool,
    mm_plan_intents: Vec<OrderIntent>,
    projected_budget_cleanup_intents: Vec<OrderIntent>,
) -> Vec<OrderIntent> {
    if pause_mm_quotes {
        return Vec::new();
    }
    if should_quote {
        if inventory_brake_cancel_only_mode {
            return retain_cancel_only_intents(mm_plan_intents);
        }
        return mm_plan_intents;
    }
    projected_budget_cleanup_intents
}

fn suppress_non_cancel_intents_for_disabled_cancel_latches(
    intents: &mut Vec<OrderIntent>,
    emergency_request_latches: &mut EmergencyRequestLatchSet,
    cfg: &Config,
    state: &GlobalState,
    now_ms: TimestampMs,
) -> Vec<usize> {
    refresh_emergency_request_latches(emergency_request_latches, cfg, state, now_ms);
    let latched_venues = emergency_request_latch_entries(
        emergency_request_latches,
        EmergencyRequestClass::DisabledCancelAll,
    )
    .iter()
    .map(|latch| latch.venue_index)
    .collect::<HashSet<_>>();
    if latched_venues.is_empty() {
        return Vec::new();
    }

    let mut suppressed = std::collections::BTreeSet::new();
    intents.retain(|intent| {
        let Some(venue_index) = venue_index_for_order_intent(intent) else {
            return true;
        };
        if !latched_venues.contains(&venue_index) {
            return true;
        }
        match intent {
            OrderIntent::Cancel(_) | OrderIntent::CancelAll(_) => true,
            OrderIntent::Place(_) | OrderIntent::Replace(_) => {
                suppressed.insert(venue_index);
                false
            }
        }
    });
    suppressed.into_iter().collect()
}

fn venue_has_material_position(cfg: &Config, state: &GlobalState, venue_index: usize) -> bool {
    let Some(venue_cfg) = cfg.venues.get(venue_index) else {
        return false;
    };
    let Some(venue) = state.venues.get(venue_index) else {
        return false;
    };
    venue.position_tao.abs() >= venue_cfg.lot_size_tao.max(1e-9)
}

fn retain_canary_breach_preferred_intents(
    cfg: &Config,
    state: &GlobalState,
    intents: &mut Vec<OrderIntent>,
    target_venues: &[usize],
    drop_cancels_for_positioned_venues: bool,
) -> usize {
    let target_venues = target_venues.iter().copied().collect::<HashSet<_>>();
    let mut removed = 0usize;
    intents.retain(|intent| {
        let Some(venue_index) = venue_index_for_order_intent(intent) else {
            return true;
        };
        if !target_venues.contains(&venue_index) {
            return true;
        }
        let drop_intent = match intent {
            OrderIntent::Place(_) | OrderIntent::Replace(_) => true,
            OrderIntent::Cancel(_) | OrderIntent::CancelAll(_) => {
                drop_cancels_for_positioned_venues
                    && venue_has_material_position(cfg, state, venue_index)
            }
        };
        if drop_intent {
            removed = removed.saturating_add(1);
            false
        } else {
            true
        }
    });
    removed
}

fn reserve_priority_path_for_inventory_control(
    soft_unwind_state: SoftUnwindRuntimeState,
    inventory_brake_pause_mm_quotes: bool,
) -> bool {
    soft_unwind_state.pause_mm_quotes || inventory_brake_pause_mm_quotes
}

fn aggressive_unwind_price(
    cfg: &Config,
    state: &GlobalState,
    venue_index: usize,
    side: Side,
) -> Option<f64> {
    let venue_cfg = cfg.venues.get(venue_index)?;
    let venue = state.venues.get(venue_index)?;
    let fair = state.fair_value.unwrap_or(state.fair_value_prev).max(1.0);
    let reference_mid = venue.mid.unwrap_or(fair).max(venue_cfg.tick_size.max(1e-9));
    let spread = venue
        .spread
        .filter(|spread| spread.is_finite() && *spread > 0.0)
        .unwrap_or(venue_cfg.tick_size.max(1e-9) * 2.0);
    let half_spread = 0.5 * spread;
    let best_bid = (reference_mid - half_spread).max(venue_cfg.tick_size.max(1e-9));
    let best_ask = (reference_mid + half_spread).max(venue_cfg.tick_size.max(1e-9));
    let cushion = half_spread.max(venue_cfg.tick_size.max(1e-9));
    Some(match side {
        Side::Buy => best_ask + cushion,
        Side::Sell => (best_bid - cushion).max(venue_cfg.tick_size.max(1e-9)),
    })
}

fn canary_exit_position_flatten_unwind_price(
    cfg: &Config,
    state: &GlobalState,
    venue_index: usize,
    side: Side,
) -> Option<f64> {
    let venue_cfg = cfg.venues.get(venue_index)?;
    let venue = state.venues.get(venue_index)?;
    let tick_size = venue_cfg.tick_size.max(1e-9);
    venue
        .mid
        .filter(|mid| mid.is_finite() && *mid >= tick_size)?;
    venue
        .spread
        .filter(|spread| spread.is_finite() && *spread > 0.0)?;
    aggressive_unwind_price(cfg, state, venue_index, side)
}

fn inventory_brake_slippage_bps_for_venue(venue_id: &str) -> f64 {
    let venue_key = venue_id.to_ascii_uppercase();
    parse_optional_positive_f64_env(
        format!("PARAPHINA_CANARY_BRAKE_UNWIND_SLIPPAGE_BPS_{venue_key}").as_str(),
    )
    .or_else(|| parse_optional_positive_f64_env("PARAPHINA_CANARY_BRAKE_UNWIND_SLIPPAGE_BPS"))
    .unwrap_or(50.0)
}

fn snap_aggressive_price_to_tick(price: f64, tick_size: f64, side: Side) -> Option<f64> {
    if !price.is_finite() || price <= 0.0 || !tick_size.is_finite() || tick_size <= 0.0 {
        return None;
    }
    let ticks = price / tick_size;
    let snapped_ticks = match side {
        Side::Buy => ticks.ceil(),
        Side::Sell => ticks.floor(),
    };
    Some((snapped_ticks * tick_size).max(tick_size))
}

fn inventory_brake_unwind_price(
    cfg: &Config,
    state: &GlobalState,
    venue_index: usize,
    side: Side,
) -> Option<f64> {
    let venue_cfg = cfg.venues.get(venue_index)?;
    let venue = state.venues.get(venue_index)?;
    let fair = state
        .fair_value
        .unwrap_or(state.fair_value_prev)
        .max(venue_cfg.tick_size.max(1e-9));
    let reference_mid = venue.mid.unwrap_or(fair).max(venue_cfg.tick_size.max(1e-9));
    let bump =
        (inventory_brake_slippage_bps_for_venue(venue_cfg.id.as_str()) / 10_000.0).max(0.0005);
    let raw_price = match side {
        Side::Buy => reference_mid * (1.0 + bump),
        Side::Sell => reference_mid * (1.0 - bump),
    };
    snap_aggressive_price_to_tick(raw_price, venue_cfg.tick_size.max(1e-9), side)
}

