    static ENV_MUTEX: OnceLock<Mutex<()>> = OnceLock::new();

    struct EnvGuard {
        saved: Vec<(String, Option<String>)>,
    }

    impl EnvGuard {
        fn new(keys: &[&str]) -> Self {
            Self {
                saved: keys
                    .iter()
                    .map(|key| ((*key).to_string(), std::env::var(key).ok()))
                    .collect(),
            }
        }
    }

    impl Drop for EnvGuard {
        fn drop(&mut self) {
            for (key, value) in self.saved.drain(..) {
                if let Some(value) = value {
                    std::env::set_var(&key, value);
                } else {
                    std::env::remove_var(&key);
                }
            }
        }
    }

    fn lighter_place_intent() -> OrderIntent {
        OrderIntent::Place(PlaceOrderIntent {
            venue_index: 0,
            venue_id: "lighter".into(),
            side: Side::Buy,
            price: 100.0,
            size: 0.01,
            purpose: OrderPurpose::Mm,
            time_in_force: TimeInForce::Gtc,
            post_only: true,
            reduce_only: false,
            client_order_id: None,
            phase51_target_key: None,
        })
    }

    fn lighter_only_config() -> Config {
        let mut cfg = Config::default();
        let lighter = cfg
            .venues
            .iter()
            .find(|venue| venue.id == "lighter")
            .cloned()
            .expect("default config includes lighter");
        cfg.venues = vec![lighter];
        cfg
    }

    fn lighter_target_key(label: &str) -> Phase51ForwardRefreshTargetKey {
        Phase51ForwardRefreshTargetKey {
            canonical_group_id: format!("cg-{label}"),
            order_key: format!("ok-{label}"),
        }
    }

    fn lighter_targeted_place_intent(side: Side, label: &str) -> OrderIntent {
        let mut intent = lighter_place_intent();
        if let OrderIntent::Place(place) = &mut intent {
            place.side = side;
            place.phase51_target_key = Some(lighter_target_key(label));
        }
        intent
    }

