    fn seed_terminal_flatten_market(state: &mut GlobalState, venue_indices: &[usize]) {
        state.fair_value = Some(2_000.0);
        for &venue_index in venue_indices {
            state.venues[venue_index].mid = Some(2_000.0);
            state.venues[venue_index].spread = Some(0.10);
        }
    }

    fn with_phase51_strict_native_role_canary_env<R>(f: impl FnOnce() -> R) -> R {
        let keys = [
            PHASE51_LIGHTER_NATIVE_ROLE_STRICT_CANARY_ENV,
            PHASE51_LIGHTER_NATIVE_ROLE_DISABLE_REPLACEMENTS_ENV,
            PHASE51_LIGHTER_NATIVE_ROLE_STOP_AFTER_FIRST_ROW_ENV,
        ];
        let _lock = ENV_MUTEX.get_or_init(|| Mutex::new(())).lock().unwrap();
        let _guard = EnvGuard::new(&keys);
        std::env::set_var(PHASE51_LIGHTER_NATIVE_ROLE_STRICT_CANARY_ENV, "true");
        std::env::set_var(PHASE51_LIGHTER_NATIVE_ROLE_DISABLE_REPLACEMENTS_ENV, "true");
        std::env::set_var(PHASE51_LIGHTER_NATIVE_ROLE_STOP_AFTER_FIRST_ROW_ENV, "true");
        f()
    }

    fn with_phase51_one_sided_native_role_canary_env<R>(side: &str, f: impl FnOnce() -> R) -> R {
        let keys = [
            PHASE51_LIGHTER_NATIVE_ROLE_STRICT_CANARY_ENV,
            PHASE51_LIGHTER_NATIVE_ROLE_ONE_SIDED_CANARY_ENV,
            PHASE51_LIGHTER_NATIVE_ROLE_ONE_SIDED_SIDE_ENV,
            PHASE51_LIGHTER_NATIVE_ROLE_DISABLE_REPLACEMENTS_ENV,
            PHASE51_LIGHTER_NATIVE_ROLE_STOP_AFTER_FIRST_ROW_ENV,
        ];
        let _lock = ENV_MUTEX.get_or_init(|| Mutex::new(())).lock().unwrap();
        let _guard = EnvGuard::new(&keys);
        std::env::set_var(PHASE51_LIGHTER_NATIVE_ROLE_STRICT_CANARY_ENV, "true");
        std::env::set_var(PHASE51_LIGHTER_NATIVE_ROLE_ONE_SIDED_CANARY_ENV, "true");
        std::env::set_var(PHASE51_LIGHTER_NATIVE_ROLE_ONE_SIDED_SIDE_ENV, side);
        std::env::set_var(PHASE51_LIGHTER_NATIVE_ROLE_DISABLE_REPLACEMENTS_ENV, "true");
        std::env::set_var(PHASE51_LIGHTER_NATIVE_ROLE_STOP_AFTER_FIRST_ROW_ENV, "true");
        f()
    }

    fn with_phase51_lighter_baseline_cleanup_only_env<R>(
        enabled: bool,
        f: impl FnOnce() -> R,
    ) -> R {
        let keys = [PHASE51_LIGHTER_BASELINE_CLEANUP_ONLY_ENV];
        let _lock = ENV_MUTEX.get_or_init(|| Mutex::new(())).lock().unwrap();
        let _guard = EnvGuard::new(&keys);
        if enabled {
            std::env::set_var(PHASE51_LIGHTER_BASELINE_CLEANUP_ONLY_ENV, "true");
        } else {
            std::env::remove_var(PHASE51_LIGHTER_BASELINE_CLEANUP_ONLY_ENV);
        }
        f()
    }

    #[test]
    fn phase51_lighter_native_role_strict_canary_rejects_replace_and_multi_place() {
        with_phase51_strict_native_role_canary_env(|| {
            assert_eq!(
                phase51_lighter_native_role_strict_canary_validate_order_intents(&[
                    lighter_replace_intent()
                ]),
                Err("replace_disabled")
            );
            assert_eq!(
                phase51_lighter_native_role_strict_canary_validate_order_intents(&[
                    lighter_place_intent(),
                    lighter_place_intent(),
                ]),
                Err("multiple_places")
            );
            assert_eq!(
                phase51_lighter_native_role_strict_canary_validate_order_intents(&[
                    lighter_cancel_intent(),
                    lighter_place_intent(),
                ]),
                Err("cancel_and_place_replacement_disabled")
            );
        });
    }

