    #[test]
    fn phase51_lighter_native_role_one_sided_canary_rejects_unsafe_replace_shapes() {
        with_phase51_one_sided_native_role_canary_env("buy", || {
            let mut intents = vec![lighter_replace_intent()];
            assert_eq!(
                phase51_lighter_native_role_apply_one_sided_canary_filter(&mut intents),
                Err("missing_phase51_target_key")
            );

            let mut wrong_side = vec![lighter_targeted_replace_intent(Side::Sell, "ask")];
            assert_eq!(
                phase51_lighter_native_role_apply_one_sided_canary_filter(&mut wrong_side),
                Err("preferred_side_absent")
            );

            let mut non_lighter = lighter_targeted_replace_intent(Side::Buy, "bid");
            if let OrderIntent::Replace(replace) = &mut non_lighter {
                replace.venue_id = "aster".into();
            }
            let mut intents = vec![non_lighter];
            assert_eq!(
                phase51_lighter_native_role_apply_one_sided_canary_filter(&mut intents),
                Err("non_lighter_replace")
            );

            let mut non_post_only = lighter_targeted_replace_intent(Side::Buy, "bid");
            if let OrderIntent::Replace(replace) = &mut non_post_only {
                replace.post_only = false;
            }
            let mut intents = vec![non_post_only];
            assert_eq!(
                phase51_lighter_native_role_apply_one_sided_canary_filter(&mut intents),
                Err("non_post_only_replace")
            );

            let mut mixed = vec![
                lighter_targeted_replace_intent(Side::Buy, "bid"),
                lighter_targeted_place_intent(Side::Buy, "bid-new"),
            ];
            assert_eq!(
                phase51_lighter_native_role_apply_one_sided_canary_filter(&mut mixed),
                Err("replace_and_place_disabled")
            );
        });
    }

    #[test]
    fn v2_live_order_path_probe_latch_requires_explicit_live_probe_mode() {
        let mut cfg = Config::default();
        assert!(!v2_live_order_path_probe_latch_enabled(&cfg));

        cfg.v2_shadow.enabled = true;
        cfg.v2_shadow.decision_mode = crate::config::V2DecisionMode::LiveCanaryAdmission;
        assert!(!v2_live_order_path_probe_latch_enabled(&cfg));

        cfg.v2_shadow.live_canary_order_path_probe_approved = true;
        assert!(v2_live_order_path_probe_latch_enabled(&cfg));
    }

    #[test]
    fn v2_live_order_path_probe_latch_removes_only_lighter_mm_order_creating_intents() {
        let mut non_lighter = lighter_targeted_place_intent(Side::Buy, "aster");
        if let OrderIntent::Place(place) = &mut non_lighter {
            place.venue_id = "aster".into();
        }
        let mut intents = vec![
            lighter_targeted_place_intent(Side::Buy, "bid"),
            lighter_cancel_intent(),
            lighter_targeted_replace_intent(Side::Buy, "replace"),
            non_lighter,
        ];

        assert!(v2_has_order_creating_probe_intent(&intents));
        assert_eq!(v2_remove_order_creating_probe_intents(&mut intents), 2);
        assert_eq!(intents.len(), 2);
        assert!(matches!(intents[0], OrderIntent::Cancel(_)));
        assert!(
            matches!(&intents[1], OrderIntent::Place(place) if place.venue_id.as_ref() == "aster")
        );
    }

    fn v2_live_canary_admission_runner_config() -> Config {
        let mut cfg = Config::default();
        cfg.v2_shadow.enabled = true;
        cfg.v2_shadow.decision_mode = crate::config::V2DecisionMode::LiveCanaryAdmission;
        cfg.v2_shadow.live_canary_admission_approved = true;
        cfg
    }

    fn with_v2_ranked_execution_env<R>(f: impl FnOnce() -> R) -> R {
        let _lock = ENV_MUTEX.get_or_init(|| Mutex::new(())).lock().unwrap();
        let _guard = EnvGuard::new(&[
            V2_DECISION_MODE_ENV,
            "PARAPHINA_V2_LIVE_CANARY_ADMISSION_APPROVED",
            V2_LIVE_CANARY_RANKED_EXECUTION_VENUES_ENV,
        ]);
        std::env::set_var(V2_DECISION_MODE_ENV, "live_canary_admission");
        std::env::set_var("PARAPHINA_V2_LIVE_CANARY_ADMISSION_APPROVED", "true");
        std::env::set_var(V2_LIVE_CANARY_RANKED_EXECUTION_VENUES_ENV, "lighter");
        f()
    }

    fn v2_lighter_targeted_place_intent(side: Side, label: &str) -> OrderIntent {
        let mut intent = lighter_targeted_place_intent(side, label);
        if let OrderIntent::Place(place) = &mut intent {
            place.venue_index = 3;
        }
        intent
    }

    fn v2_lighter_targeted_replace_intent(side: Side, suffix: &str) -> OrderIntent {
        let mut intent = lighter_targeted_replace_intent(side, suffix);
        if let OrderIntent::Replace(replace) = &mut intent {
            replace.venue_index = 3;
        }
        intent
    }

    fn v2_lighter_cancel_intent() -> OrderIntent {
        let mut intent = lighter_cancel_intent();
        if let OrderIntent::Cancel(cancel) = &mut intent {
            cancel.venue_index = 3;
        }
        intent
    }

