    #[test]
    fn terminal_exit_quiesce_cancel_intents_send_once_and_reset_after_clean() {
        let cfg = Config::default();
        let mut state = GlobalState::new(&cfg);
        let hyperliquid = 1;
        let lighter = 3;
        let mut cancel_state = vec![TerminalExitCancelState::default(); cfg.venues.len()];
        let now_ms = 45_000;

        seed_open_orders(&mut state, hyperliquid, 2, now_ms);
        seed_open_orders(&mut state, lighter, 1, now_ms);

        let intents = build_terminal_exit_quiesce_cancel_intents(
            &cfg,
            &state,
            &mut cancel_state,
            now_ms,
            0,
            None,
        );
        assert_eq!(intents.len(), 3);
        assert_eq!(cancel_state[hyperliquid].first_sent_ms, Some(now_ms));
        assert_eq!(cancel_state[lighter].first_sent_ms, Some(now_ms));
        assert_eq!(
            intents
                .iter()
                .filter(|intent| matches!(intent, OrderIntent::Cancel(_)))
                .count(),
            2
        );
        assert_eq!(
            intents
                .iter()
                .filter(|intent| matches!(intent, OrderIntent::CancelAll(_)))
                .count(),
            1
        );

        let duplicate = build_terminal_exit_quiesce_cancel_intents(
            &cfg,
            &state,
            &mut cancel_state,
            now_ms + 1_000,
            0,
            None,
        );
        assert!(duplicate.is_empty());

        let clean_state = GlobalState::new(&cfg);
        let clean = build_terminal_exit_quiesce_cancel_intents(
            &cfg,
            &clean_state,
            &mut cancel_state,
            now_ms + 2_000,
            0,
            None,
        );
        assert!(clean.is_empty());
        assert_eq!(cancel_state[hyperliquid].first_sent_ms, None);
        assert_eq!(cancel_state[lighter].first_sent_ms, None);

        seed_open_orders(&mut state, lighter, 1, 46_000);
        let resent = build_terminal_exit_quiesce_cancel_intents(
            &cfg,
            &state,
            &mut cancel_state,
            now_ms + 3_000,
            0,
            None,
        );
        assert!(!resent.is_empty());
        assert_eq!(cancel_state[lighter].first_sent_ms, Some(now_ms + 3_000));
    }

    #[test]
    fn canary_exit_cancel_all_enabled_requires_live_canary_opt_in() {
        let _lock = ENV_MUTEX.get_or_init(|| Mutex::new(())).lock().unwrap();
        let _guard = EnvGuard::new(&[
            "PARAPHINA_CANARY_EXIT_CANCEL_ALL_ENABLED",
            "PARAPHINA_CANARY_EXIT_CANCEL_ALL_ATTEMPTS",
            "PARAPHINA_CANARY_EXIT_CANCEL_ALL_SETTLE_MS",
            "PARAPHINA_CANARY_EXIT_CANCEL_ALL_TIMEOUT_MS",
            "PARAPHINA_CANARY_EXIT_CANCEL_ALL_SWEEP_ALL_VENUES",
            "PARAPHINA_CANARY_EXIT_POSITION_FLATTEN_ENABLED",
            "PARAPHINA_CANARY_EXIT_POSITION_FLATTEN_TOL_TAO",
            "PARAPHINA_CANARY_EXIT_POSITION_FLATTEN_ATTEMPTS",
            "PARAPHINA_CANARY_EXIT_POSITION_FLATTEN_SETTLE_MS",
            "PARAPHINA_LIGHTER_TERMINAL_REDUCE_DUST_TO_MIN_LOT",
        ]);

        std::env::remove_var("PARAPHINA_CANARY_EXIT_CANCEL_ALL_ENABLED");
        std::env::remove_var("PARAPHINA_CANARY_EXIT_CANCEL_ALL_TIMEOUT_MS");
        std::env::remove_var("PARAPHINA_CANARY_EXIT_CANCEL_ALL_SWEEP_ALL_VENUES");
        assert!(!canary_exit_cancel_all_enabled(true));
        assert_eq!(canary_exit_cancel_all_timeout_ms(5), 5_000);
        assert!(!canary_exit_cancel_all_sweep_all_venues_enabled());

        std::env::set_var("PARAPHINA_CANARY_EXIT_CANCEL_ALL_ENABLED", "true");
        assert!(canary_exit_cancel_all_enabled(true));
        assert!(!canary_exit_cancel_all_enabled(false));

        std::env::set_var("PARAPHINA_CANARY_EXIT_CANCEL_ALL_SWEEP_ALL_VENUES", "true");
        assert!(canary_exit_cancel_all_sweep_all_venues_enabled());
        std::env::set_var("PARAPHINA_CANARY_EXIT_CANCEL_ALL_SWEEP_ALL_VENUES", "0");
        assert!(!canary_exit_cancel_all_sweep_all_venues_enabled());

        std::env::set_var("PARAPHINA_CANARY_EXIT_CANCEL_ALL_ENABLED", "0");
        assert!(!canary_exit_cancel_all_enabled(true));

        std::env::set_var("PARAPHINA_CANARY_EXIT_CANCEL_ALL_ATTEMPTS", "0");
        std::env::set_var("PARAPHINA_CANARY_EXIT_CANCEL_ALL_SETTLE_MS", "20000");
        std::env::set_var("PARAPHINA_CANARY_EXIT_CANCEL_ALL_TIMEOUT_MS", "40000");
        assert_eq!(canary_exit_cancel_all_attempts(), 3);
        assert_eq!(canary_exit_cancel_all_settle_ms(), 10_000);
        assert_eq!(canary_exit_cancel_all_timeout_ms(5), 30_000);
        std::env::set_var("PARAPHINA_CANARY_EXIT_CANCEL_ALL_TIMEOUT_MS", "250");
        assert_eq!(canary_exit_cancel_all_timeout_ms(5), 1_000);

        std::env::remove_var("PARAPHINA_CANARY_EXIT_POSITION_FLATTEN_ENABLED");
        assert!(!canary_exit_position_flatten_enabled(true));
        std::env::set_var("PARAPHINA_CANARY_EXIT_POSITION_FLATTEN_ENABLED", "true");
        assert!(canary_exit_position_flatten_enabled(true));
        assert!(!canary_exit_position_flatten_enabled(false));
        std::env::set_var("PARAPHINA_CANARY_EXIT_POSITION_FLATTEN_TOL_TAO", "0.001");
        assert_eq!(canary_exit_position_flatten_tol_tao(), 0.001);
        std::env::set_var("PARAPHINA_CANARY_EXIT_POSITION_FLATTEN_TOL_TAO", "0.1");
        assert_eq!(canary_exit_position_flatten_tol_tao(), 0.01);
        assert_eq!(canary_exit_position_flatten_attempts(), 3);
        assert_eq!(canary_exit_position_flatten_settle_ms(), 1_000);
        std::env::set_var("PARAPHINA_CANARY_EXIT_POSITION_FLATTEN_ATTEMPTS", "0");
        std::env::set_var("PARAPHINA_CANARY_EXIT_POSITION_FLATTEN_SETTLE_MS", "20000");
        assert_eq!(canary_exit_position_flatten_attempts(), 3);
        assert_eq!(canary_exit_position_flatten_settle_ms(), 10_000);
        std::env::set_var("PARAPHINA_CANARY_EXIT_POSITION_FLATTEN_ATTEMPTS", "9");
        assert_eq!(canary_exit_position_flatten_attempts(), 5);
        std::env::set_var("PARAPHINA_CANARY_EXIT_POSITION_FLATTEN_ATTEMPTS", "1");
        assert_eq!(canary_exit_position_flatten_attempts(), 1);

        std::env::remove_var("PARAPHINA_LIGHTER_TERMINAL_REDUCE_DUST_TO_MIN_LOT");
        assert!(!lighter_terminal_reduce_dust_to_min_lot_enabled());
        std::env::set_var("PARAPHINA_LIGHTER_TERMINAL_REDUCE_DUST_TO_MIN_LOT", "true");
        assert!(lighter_terminal_reduce_dust_to_min_lot_enabled());
        std::env::set_var("PARAPHINA_LIGHTER_TERMINAL_REDUCE_DUST_TO_MIN_LOT", "0");
        assert!(!lighter_terminal_reduce_dust_to_min_lot_enabled());
    }

